/* Inspections / Toolbox talks page (job menu). One page for both: cbs-job-inspections (req scaffold) and cbs-job-toolbox (req toolbox).
   Items are the job's task rows (cbs_job_tasks, req scaffold/toolbox), the same ones the Actions board and TV read.
   Add / edit / remove: POST cbs-admin-save (t=jobtasks). Reports: POST cbs-job-upload (SharePoint), then the item is marked done,
   last done = today and the next due date follows the frequency. CBS does not carry out inspections: the contractor sends a report. */
const it = $input.first().json;
const url = String(it.webhookUrl || '');
const K = /cbs-job-toolbox/.test(url) ? 'toolbox' : 'scaffold';
const job = String((it.query || {}).job || '').replace(/[^0-9A-Za-z-]/g, '');
const C = K === 'toolbox' ? {
  k: 'toolbox', title: 'Toolbox talks', one: 'toolbox talk', typeLab: 'Topic', byLab: 'Given by', folder: 'Toolbox talks', fin: 'Held',
  st: ['Not held', 'Booked', 'Held'], add: '+ Add toolbox talk', up: 'Upload record',
  help: 'Plan toolbox talks for this job and how often they happen. Upload the signed record after each talk; the next one is then due by the frequency. Talks built with the toolbox talk builder are listed under Talks held.',
  empty: 'No toolbox talks planned for this job yet.',
  types: ['Working at height', 'Manual handling', 'Slips, trips and falls', 'Dust and silica', 'Hand-arm vibration', 'Noise', 'Fire safety', 'Electrical safety', 'Plant and machinery', 'PPE', 'Asbestos awareness', 'Other']
} : {
  k: 'scaffold', title: 'Inspections', one: 'inspection', typeLab: 'Inspection type', byLab: 'Carried out by', folder: 'Inspections', fin: 'Inspected',
  st: ['Not booked', 'Booked', 'Inspected', 'Re-inspection needed'], add: '+ Add inspection', up: 'Upload report',
  help: 'Inspections are carried out by the specialist contractor (scaffolder, LOLER engineer and so on), who sends a report. Add each inspection the job needs and how often, then upload the report when it comes in; the next one is then due by the frequency. Scaffolds: before first use, at least every 7 days, and after bad weather or alterations.',
  empty: 'No inspections set up for this job yet.',
  types: ['Scaffold', 'Lifting equipment (LOLER)', 'Excavation', 'Temporary works', 'MEWP / access equipment', 'Hoist', 'Fire safety', 'Electrical installation', 'PAT testing', 'Asbestos re-inspection', 'Other']
};
const CSS = '*{box-sizing:border-box}body{margin:0;background:#f2f2f0;color:#161616;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;font-size:16px;line-height:1.4}'
 + 'header{background:#3d4043;color:#fff;padding:12px 16px;border-bottom:4px solid #F47920;position:sticky;top:0;z-index:5}header .nav{display:flex;flex-wrap:wrap;gap:6px 14px}header a.hub{color:#ffb37a;font-size:13px;text-decoration:none}header h1{margin:4px 0 0;font-size:20px}header p{margin:3px 0 0;color:#ccc;font-size:13px}'
 + '.wrap{max-width:860px;margin:0 auto;padding:14px}.tools{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:8px}'
 + '.btn{background:#F47920;color:#fff;font-weight:600;border-radius:8px;padding:9px 14px;font-size:14px;border:1px solid #F47920;font-family:inherit;cursor:pointer;text-decoration:none;display:inline-block;line-height:1.2}.btn.ghost{background:#fff;color:#1d1d1d;border-color:#3d4043}.btn.red{background:#fff;color:#b3261e;border-color:#e9b6b1}.btn.sm{padding:6px 10px;font-size:13px}.btn:disabled{opacity:.5;cursor:wait}'
 + '.m{color:#6b6e70;font-size:13.5px}.help{margin:4px 0 14px}.it{background:#fff;border:1px solid #d9d9d6;border-radius:12px;padding:12px 14px;margin-bottom:10px}.hd{display:flex;gap:10px;align-items:flex-start}.tt{flex:1;font-weight:700}'
 + '.ch{display:inline-block;font-size:12.5px;font-weight:600;border-radius:6px;padding:2px 8px;white-space:nowrap}.ch.r{background:#fde7e5;color:#b3261e}.ch.a{background:#fff1d6;color:#8a5300}.ch.g{background:#e6f4ea;color:#1a7f37}'
 + '.it .m{margin-top:4px}.nt{font-size:14px;margin-top:6px;white-space:pre-wrap}.fl{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}.fl a{font-size:13px;color:#b3261e;font-weight:600;border:1px solid #d9d9d6;border-radius:6px;padding:3px 8px;text-decoration:none;max-width:260px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}'
 + '.b{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}.empty{color:#6b6e70;padding:18px 14px;text-align:center;background:#fff;border:1px dashed #d9d9d6;border-radius:12px}h2{font-size:16px;margin:22px 0 8px}'
 + '.hl{background:#fff;border:1px solid #d9d9d6;border-radius:12px}.hl .r{display:flex;gap:10px;align-items:center;padding:10px 14px;border-top:1px solid #f0f0ee}.hl .r:first-child{border-top:0}.hl .r .x{flex:1;min-width:0}'
 + '.ov{position:fixed;inset:0;background:rgba(0,0,0,.45);display:flex;align-items:flex-start;justify-content:center;padding:20px 10px;overflow:auto;z-index:2147483300}.dlg{background:#fff;border-radius:14px;max-width:520px;width:100%;padding:16px}.dlg h3{margin:0 0 10px;font-size:18px}'
 + 'label.f{display:block;font-size:13px;font-weight:600;color:#444;margin:10px 0 4px}.dlg input,.dlg select,.dlg textarea{width:100%;font:inherit;padding:10px;border:1px solid #c4c6c8;border-radius:8px;background:#fff}.row2{display:grid;grid-template-columns:1fr 1fr;gap:8px}.msg{font-size:14px;color:#8a5a00;margin-top:8px;min-height:18px}'
 + '@media(max-width:560px){.row2{grid-template-columns:1fr}}';
const nav = '<div class="nav"><a class="hub" href="/webhook/cbs-admin">&larr; Operations Hub</a><a class="hub" href="/webhook/cbs-job-file?job=' + encodeURIComponent(job) + '">Job</a></div>';
const html = '<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + C.title + ' - Job ' + job + '</title><script src="/webhook/cbs-guard"></script><style>' + CSS + '</style></head><body><header>' + nav + '<h1>' + C.title + '</h1><p>Job ' + job + '</p></header><div class="wrap" id="app"><div class="empty">' + (job ? 'Loading\u2026' : 'Open this page from a job.') + '</div></div>'
 + (job ? '<script>(' + client.toString() + ')(' + JSON.stringify(C).replace(/</g, '\\u003c') + ',' + JSON.stringify(job) + ');</script>' : '') + '</body></html>';
return [{ json: { html: html } }];

function client(C, JOB) {
  var app = document.getElementById('app'), D = null, MO = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  function s(v){return v==null?'':String(v);}
  function e(t){return s(t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
  function today(){return new Date().toLocaleDateString('en-CA',{timeZone:'Europe/London'});}
  function now(){return new Date().toLocaleString('sv-SE',{timeZone:'Europe/London'}).replace(' ','T').slice(0,16);}
  function dn(d){var m=s(d).match(/^(\d{4})-(\d{2})-(\d{2})/);return m?Date.UTC(+m[1],+m[2]-1,+m[3])/864e5:null;}
  function ukd(d){var m=s(d).match(/^(\d{4})-(\d{2})-(\d{2})/);return m?Number(m[3])+' '+MO[+m[2]-1]:'';}
  function addF(d,f){var x=dn(d);if(x===null||!f)return '';f=s(f).toLowerCase();var n=0,mo=0,m;if(f==='daily')n=1;else if(f==='weekly')n=7;else if(f==='fortnightly')n=14;else if(f==='monthly')mo=1;else if((m=f.match(/every\s+(\d+)\s*day/)))n=+m[1];else return '';var dt=new Date(x*864e5);if(mo)dt.setUTCMonth(dt.getUTCMonth()+1);else dt.setUTCDate(dt.getUTCDate()+n);return dt.toISOString().slice(0,10);}
  function nextDue(r){var f=s(r.freq),ld=s(r.last_done).slice(0,10);if(f&&ld)return addF(ld,f);return s(r.due_on).slice(0,10);}
  function state(r){var st=s(r.status),nd=nextDue(r),d=nd?dn(nd)-dn(today()):null;
    if(st==='Re-inspection needed')return {c:'r',t:'Re-inspection needed'};
    if(d!==null&&d<0)return {c:'r',t:'Overdue \u00b7 was due '+ukd(nd)};
    if(st===C.fin&&!s(r.freq))return {c:'g',t:C.fin+(r.last_done?' '+ukd(r.last_done):'')};
    if(d!==null&&d<=2)return {c:'a',t:d===0?'Due today':'Due '+ukd(nd)};
    if(st===C.fin||s(r.last_done))return {c:'g',t:'Up to date'+(nd?' \u00b7 next '+ukd(nd):'')};
    if(st==='Booked')return {c:'a',t:'Booked'+(nd?' for '+ukd(nd):'')};
    return {c:'a',t:(st||C.st[0])+(nd?' \u00b7 due '+ukd(nd):'')};}
  function files(r){try{var a=JSON.parse(r.files_json||'[]');return Array.isArray(a)?a:[];}catch(x){return [];}}
  function fileUrl(u){return /sharepoint\.com/i.test(s(u))?'/webhook/cbs-file?u='+encodeURIComponent(u):s(u);}
  function who(){var x='';try{var m=JSON.parse(localStorage.getItem('cbs_me')||'null');if(m&&m.name)x=m.name;}catch(z){}if(!x){try{x=localStorage.getItem('cbs_name')||'';}catch(z){}}if(!x){x=(prompt('Your name:')||'').trim();if(x){try{localStorage.setItem('cbs_name',x);}catch(z){}}}return x;}
  function post(u,b){return fetch(u,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b||{})}).then(function(r){if(!r.ok)throw 0;return r.json();}).then(function(d){if(!d||d.ok===false)throw 0;return d;});}
  function load(){fetch('/webhook/cbs-job-sched-data?job='+encodeURIComponent(JOB)+'&k='+C.k+'&_='+Date.now(),{cache:'no-store'}).then(function(r){return r.json();}).then(function(d){D=d||{};var p=document.querySelector('header p');if(p&&D.site)p.textContent='Job '+JOB+' \u00b7 '+D.site;render();}).catch(function(){app.innerHTML='<div class="empty">Could not load. Refresh to try again.</div>';});}
  function render(){var L=(D.items||[]).slice().sort(function(a,b){var x=nextDue(a)||'9999',y=nextDue(b)||'9999';return x<y?-1:x>y?1:0;}),h='';
    h+='<div class="tools"><button class="btn" id="add">'+e(C.add)+'</button>'+(C.k==='toolbox'?'<a class="btn ghost" href="/webhook/cbs-toolbox-builder?job='+encodeURIComponent(JOB)+'">Build a toolbox talk</a>':'')+'</div><p class="m help">'+e(C.help)+'</p>';
    if(!L.length)h+='<div class="empty">'+e(C.empty)+'</div>';
    L.forEach(function(r){var S=state(r),F=files(r),nd=nextDue(r),by=r.label&&r.label!==r.ref_name?r.label:'';
      h+='<div class="it" data-id="'+e(r.id)+'"><div class="hd"><div class="tt">'+e(r.ref_name||r.label||C.one)+'</div><span class="ch '+S.c+'">'+e(S.t)+'</span></div>'
       +'<div class="m">'+[by?e(C.byLab+': '+by):'',r.freq?e(r.freq):'One-off',r.last_done?'Last '+e(ukd(r.last_done)):'',nd?'Next due '+e(ukd(nd)):''].filter(Boolean).join(' \u00b7 ')+'</div>'
       +(r.notes?'<div class="nt">'+e(r.notes)+'</div>':'')
       +(F.length?'<div class="fl">'+F.map(function(f){return '<a href="'+e(fileUrl(f.u))+'" target="_blank" rel="noopener" title="'+e(f.n||'PDF')+'">'+e(f.n||'PDF')+'</a>';}).join('')+'</div>':'')
       +'<div class="b"><button class="btn sm" data-a="up">'+e(C.up)+'</button><button class="btn ghost sm" data-a="edit">Edit</button><button class="btn red sm" data-a="rm">Remove</button></div></div>';});
    var HL=D.held||[];if(C.k==='toolbox')h+='<h2>Talks held</h2>'+(HL.length?'<div class="hl">'+HL.map(function(t){return '<div class="r"><div class="x"><b>'+e(t.topic||'Toolbox talk')+'</b><div class="m">'+[ukd(t.held_on),t.presenter].filter(Boolean).map(e).join(' \u00b7 ')+'</div></div>'+(t.pdf?'<a class="btn ghost sm" target="_blank" rel="noopener" href="'+e(fileUrl(t.pdf))+'">PDF</a>':'')+'</div>';}).join('')+'</div>':'<div class="empty">No toolbox talks held on this job yet.</div>');
    app.innerHTML=h;
    document.getElementById('add').onclick=function(){dlg(null);};
    [].forEach.call(app.querySelectorAll('.it [data-a]'),function(b){b.onclick=function(){var id=b.closest('.it').getAttribute('data-id'),r=(D.items||[]).filter(function(x){return String(x.id)===id;})[0];if(!r)return;var a=b.getAttribute('data-a');if(a==='edit')dlg(r);else if(a==='rm')rm(r);else upload(r,b);};});}
  var FQ=[['','One-off'],['Daily','Daily'],['Weekly','Weekly'],['Fortnightly','Fortnightly'],['Monthly','Monthly'],['custom','Every \u2026 days']];
  function dlg(r){var isNew=!r;r=r||{};var fq=s(r.freq),m=fq.match(/^every\s+(\d+)\s*days?$/i),cv=m?'custom':fq,by=r.label&&r.label!==r.ref_name?r.label:'',sts=C.st.slice();if(r.status&&sts.indexOf(r.status)<0)sts.push(r.status);
    var o=document.createElement('div');o.className='ov';
    o.innerHTML='<div class="dlg"><h3>'+(isNew?e(C.add.replace(/^\+ /,'')):'Edit '+e(C.one))+'</h3>'
     +'<label class="f">'+e(C.typeLab)+'</label><input id="fT" list="fTl" value="'+e(r.ref_name||'')+'" placeholder="Choose or type"><datalist id="fTl">'+C.types.map(function(t){return '<option value="'+e(t)+'">';}).join('')+'</datalist>'
     +'<label class="f">'+e(C.byLab)+'</label><input id="fB" list="fBl" value="'+e(by)+'" placeholder="'+(C.k==='toolbox'?'Who gives the talk':'Contractor')+'"><datalist id="fBl">'+(D.people||[]).map(function(t){return '<option value="'+e(t)+'">';}).join('')+'</datalist>'
     +'<div class="row2"><div><label class="f">How often</label><select id="fF">'+FQ.map(function(x){return '<option value="'+e(x[0])+'"'+(x[0]===cv?' selected':'')+'>'+e(x[1])+'</option>';}).join('')+(cv&&!FQ.some(function(x){return x[0]===cv;})?'<option selected>'+e(cv)+'</option>':'')+'</select><input id="fN" type="number" min="1" placeholder="Number of days" value="'+(m?m[1]:'')+'" style="margin-top:6px;'+(cv==='custom'?'':'display:none')+'"></div>'
     +'<div><label class="f">'+(isNew?'First due':'Due')+'</label><input id="fD" type="date" value="'+e(s(r.due_on).slice(0,10))+'"></div></div>'
     +'<label class="f">Status</label><select id="fS">'+sts.map(function(x){return '<option'+(x===(r.status||C.st[0])?' selected':'')+'>'+e(x)+'</option>';}).join('')+'</select>'
     +'<label class="f">Notes</label><textarea id="fX" rows="3">'+e(r.notes||'')+'</textarea>'
     +'<div class="msg" id="fM"></div><div class="b"><button class="btn" id="fGo">Save</button><button class="btn ghost" id="fNo">Cancel</button></div></div>';
    document.body.appendChild(o);var Q=function(i){return o.querySelector('#'+i);};
    Q('fF').onchange=function(){Q('fN').style.display=this.value==='custom'?'':'none';if(this.value==='custom')Q('fN').focus();};
    function close(){o.remove();}Q('fNo').onclick=close;o.onclick=function(ev){if(ev.target===o)close();};
    Q('fGo').onclick=function(){var t=Q('fT').value.trim(),b=Q('fB').value.trim(),f=Q('fF').value,st=Q('fS').value,d=Q('fD').value,nt=Q('fX').value.trim(),M=Q('fM');
      if(!t){M.textContent='Enter the '+C.typeLab.toLowerCase()+'.';return;}
      if(f==='custom'){var n=parseInt(Q('fN').value,10);if(!(n>0)){M.textContent='Enter the number of days.';return;}f='Every '+n+' days';}
      var me=who();if(!me)return;var fin=st===C.fin,btn=this;btn.disabled=true;M.textContent='Saving\u2026';
      var body={ref_name:t,label:b||t,freq:f,due_on:d,status:st,notes:nt};
      if(isNew){body.job_no=JOB;body.req=C.k;body.kind='item';body.ref_id='';body.files_json='[]';body.last_done=fin?today():'';body.done_by=fin?me:'';body.done_at=fin?now():'';body.created_by=me;body.created_at=now();}
      else if(st!==r.status){body.done_by=fin?me:'';body.done_at=fin?now():'';if(fin&&!r.last_done)body.last_done=today();}
      post('/webhook/cbs-admin-save?a=save&t=jobtasks&id='+(isNew?'0':encodeURIComponent(r.id)+'&partial=1'),body).then(function(){close();load();}).catch(function(){btn.disabled=false;M.textContent='Could not save. Check the connection and try again.';});};
    setTimeout(function(){Q('fT').focus();},50);}
  function rm(r){if(!confirm('Remove '+(r.ref_name||C.one)+'? Uploaded reports stay in SharePoint.'))return;post('/webhook/cbs-admin-save?a=del&t=jobtasks&id='+encodeURIComponent(r.id),{}).then(load).catch(function(){alert('Could not remove. Try again.');});}
  function b64(f){return new Promise(function(res,rej){var x=new FileReader();x.onload=function(){res(String(x.result).split(',')[1]||'');};x.onerror=function(){rej(0);};x.readAsDataURL(f);});}
  function upload(r,btn){var fi=document.createElement('input');fi.type='file';fi.accept='application/pdf,image/*';fi.onchange=function(){var f=fi.files&&fi.files[0];if(!f)return;
      if(f.size>10*1024*1024){alert(f.name+' is over 10 MB. Compress it and try again.');return;}
      var me=who();if(!me)return;btn.disabled=true;btn.textContent='Uploading\u2026';
      b64(f).then(function(d){return post('/webhook/cbs-job-upload',{job:JOB,folder:C.folder,filename:f.name,mime:f.type||'application/pdf',data:d});}).then(function(x){if(!x||!x.u)throw 0;
        var F=files(r);F.push({n:x.n||f.name,u:x.u});var t=today(),nx=addF(t,r.freq);
        var body={files_json:JSON.stringify(F),status:C.fin,last_done:t,done_by:me,done_at:now()};if(nx)body.due_on=nx;
        return post('/webhook/cbs-admin-save?a=save&t=jobtasks&id='+encodeURIComponent(r.id)+'&partial=1',body);}).then(function(){load();}).catch(function(){btn.disabled=false;btn.textContent=C.up;alert('Upload failed. Check the connection and try again.');});};
    fi.click();}
  load();
}

/* Data for the Inspections / Toolbox talks page: the job's task rows for that kind (req scaffold or toolbox), the site,
   people for the 'carried out by' / 'given by' list, and toolbox talks held on the job (cbs_toolbox). */
const S = v => v == null ? '' : String(v).trim();
const jk = v => S(v).replace(/^#/, '').replace(/[^0-9A-Za-z-]/g, '').toLowerCase();
const q = $('GET cbs-job-sched-data').first().json.query || {};
const job = jk(q.job), K = S(q.k) === 'toolbox' ? 'toolbox' : 'scaffold';
function rows(n) { try { return $(n).all().map(i => i.json).filter(r => r && r.id != null); } catch (e) { return []; } }
const items = rows('Task Rows').filter(r => jk(r.job_no) === job && S(r.req) === K).map(r => ({ id: r.id, ref_name: S(r.ref_name), label: S(r.label), freq: S(r.freq), last_done: S(r.last_done), due_on: S(r.due_on), status: S(r.status), notes: S(r.notes), files_json: S(r.files_json) || '[]', done_by: S(r.done_by) }));
const jr = rows('Job Rows').filter(r => jk(r.ref) === job).sort((a, b) => b.id - a.id)[0] || {};
let people = [];
if (K === 'toolbox') people = rows('Worker Rows').filter(r => r.active !== false).map(r => S(r.name));
else people = rows('Subbie Rows').map(r => S(r.company));
people = Array.from(new Set(people.filter(Boolean))).sort((a, b) => a.localeCompare(b));
const held = K === 'toolbox' ? rows('Toolbox Rows').filter(r => jk(r.job_no) === job).map(r => ({ topic: S(r.topic), held_on: S(r.held_on), presenter: S(r.presenter), pdf: S(r.pdf_url) })).sort((a, b) => b.held_on.localeCompare(a.held_on)) : [];
return [{ json: { ok: true, job: job, k: K, site: S(jr.site) || S(jr.name), items: items, people: people, held: held } }];

/* Inspections / Toolbox talks page (job menu). One page for both: cbs-job-inspections (req scaffold) and cbs-job-toolbox (req toolbox).
   Items are the job's task rows (cbs_job_tasks, req scaffold/toolbox), the same ones the Actions board and TV read.
   Add / edit / remove: POST cbs-admin-save (t=jobtasks). Reports: POST cbs-job-upload (SharePoint), then the item is marked done,
   last done = today and the next due date follows the frequency. CBS does not carry out inspections: the contractor sends a report. */
const it = $input.first().json;
const url = String(it.webhookUrl || '');
const K = /cbs-job-toolbox/.test(url) ? 'toolbox' : 'scaffold';
const job = String((it.query || {}).job || '').replace(/[^0-9A-Za-z-]/g, '');
const C = K === 'toolbox' ? {
  k: 'toolbox', title: 'Toolbox talks', one: 'toolbox talk', typeLab: 'Topic', byLab: 'Given by', folder: 'Toolbox talks', fin: 'Held',
  st: ['Not held', 'Booked', 'Held'], add: '+ Add toolbox talk', up: 'Upload record',
  help: 'Plan toolbox talks for this job and how often they happen. Upload the signed record after each talk; the next one is then due by the frequency. Talks built with the toolbox talk builder are listed under Talks held.',
  empty: 'No toolbox talks planned for this job yet.',
  types: ['Working at height', 'Manual handling', 'Slips, trips and falls', 'Dust and silica', 'Hand-arm vibration', 'Noise', 'Fire safety', 'Electrical safety', 'Plant and machinery', 'PPE', 'Asbestos awareness', 'Other']
} : {
  k: 'scaffold', title: 'Inspections', one: 'inspection', typeLab: 'Inspection type', byLab: 'Carried out by', folder: 'Inspections', fin: 'Inspected',
  st: ['Not booked', 'Booked', 'Inspected', 'Re-inspection needed'], add: '+ Add inspection', up: 'Upload report',
  help: 'Inspections are carried out by the specialist contractor (scaffolder, LOLER engineer and so on), who sends a report. Add each inspection the job needs and how often, then upload the report when it comes in; the next one is then due by the frequency. Scaffolds: before first use, at least every 7 days, and after bad weather or alterations.',
  empty: 'No inspections set up for this job yet.',
  types: ['Scaffold', 'Lifting equipment (LOLER)', 'Excavation', 'Temporary works', 'MEWP / access equipment', 'Hoist', 'Fire safety', 'Electrical installation', 'PAT testing', 'Asbestos re-inspection', 'Other']
};
