  var FQ=[['','One-off'],['Daily','Daily'],['Weekly','Weekly'],['Fortnightly','Fortnightly'],['Monthly','Monthly'],['custom','Every \u2026 days']];
  function dlg(r){var isNew=!r;r=r||{};var fq=s(r.freq),m=fq.match(/^every\s+(\d+)\s*days?$/i),cv=m?'custom':fq,by=r.label&&r.label!==r.ref_name?r.label:'',sts=C.st.slice();if(r.status&&sts.indexOf(r.status)<0)sts.push(r.status);
