     +'<label class="f">'+e(C.byLab)+'</label><input id="fB" list="fBl" value="'+e(by)+'" placeholder="'+(C.k==='toolbox'?'Who gives the talk':'Contractor')+'"><datalist id="fBl">'+(D.people||[]).map(function(t){return '<option value="'+e(t)+'">';}).join('')+'</datalist>'
     +'<div class="row2"><div><label class="f">How often</label><select id="fF">'+FQ.map(function(x){return '<option value="'+e(x[0])+'"'+(x[0]===cv?' selected':'')+'>'+e(x[1])+'</option>';}).join('')+(cv&&!FQ.some(function(x){return x[0]===cv;})?'<option selected>'+e(cv)+'</option>':'')+'</select><input id="fN" type="number" min="1" placeholder="Number of days" value="'+(m?m[1]:'')+'" style="margin-top:6px;'+(cv==='custom'?'':'display:none')+'"></div>'
     +'<div><label class="f">'+(isNew?'First due':'Due')+'</label><input id="fD" type="date" value="'+e(s(r.due_on).slice(0,10))+'"></div></div>'
     +'<label class="f">Status</label><select id="fS">'+sts.map(function(x){return '<option'+(x===(r.status||C.st[0])?' selected':'')+'>'+e(x)+'</option>';}).join('')+'</select>'
